    private void check(boolean value,String label){if(!value)throw new AssertionError(label);checks++;}
    private static Object field(Object target,String name)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}
    private static void invoke(Object target,String name){try{Method m=target.getClass().getDeclaredMethod(name);m.setAccessible(true);m.invoke(target);}catch(Exception e){throw new RuntimeException(e);}}
    private static void invokeLoad(Object target,int direction){try{Method m=target.getClass().getDeclaredMethod("load",int.class,long.class);m.setAccessible(true);m.invoke(target,direction,0L);}catch(Exception e){throw new RuntimeException(e);}}
    private interface Visitor{void visit(View view);}
    private static void walk(View v,Visitor visitor){visitor.visit(v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)walk(((ViewGroup)v).getChildAt(i),visitor);}
    private View findText(Activity activity,String value){final View[] hit={null};runOnMainSync(()->walk(activity.getWindow().getDecorView(),v->{if(v.isShown()&&v instanceof TextView&&value.contentEquals(((TextView)v).getText()))hit[0]=v;}));return hit[0];}
    private View awaitText(Activity activity,String value){for(int i=0;i<100;i++){View v=findText(activity,value);if(v!=null)return v;SystemClock.sleep(100);}capture("snap-failure");throw new AssertionError("Missing text: "+value+" root="+dump(getUiAutomation().getRootInActiveWindow()));}
