    private void setDialogText(String value){for(int i=0;i<100;i++){AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();AccessibilityNodeInfo edit=findEdit(root);if(edit!=null){Bundle arguments=new Bundle();arguments.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,value);if(edit.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,arguments))return;}SystemClock.sleep(100);}throw new AssertionError("Group name field missing");}
