    private View awaitDescription(Activity activity,String value){for(int i=0;i<100;i++){final View[] hit={null};runOnMainSync(()->walk(activity.getWindow().getDecorView(),v->{if(value.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))hit[0]=v;}));if(hit[0]!=null)return hit[0];SystemClock.sleep(100);}return null;}
    private void tap(View view){check(view!=null,"Tap target exists");final int[] loc=new int[2];runOnMainSync(()->view.getLocationOnScreen(loc));float x=loc[0]+view.getWidth()/2f,y=loc[1]+view.getHeight()/2f;long t=SystemClock.uptimeMillis();sendPointerSync(MotionEvent.obtain(t,t,MotionEvent.ACTION_DOWN,x,y,0));sendPointerSync(MotionEvent.obtain(t,t+60,MotionEvent.ACTION_UP,x,y,0));waitForIdleSync();}
